com.mirth.connect.plugins.javascriptstep.script:
var request = olCoreReadHttpRequest(
    sourceMap,
    connectorMessage.getRawData()
);

olRouteApply(
    request,
    channelMap,
    'https://middleware.local.omnilink.ch',
    logger
);

channelMap.remove('fhirJson');

var rawResponse = response.getMessage();
var responseBody =
    rawResponse == null ? '' : String(rawResponse);

channelMap.put('middlewareResponse', responseBody);

/*
 * Status direkt aus der Connector Map dieses HTTP Senders lesen.
 */
var rawStatus = connectorMap.get('responseStatusCode');
var statusText =
    rawStatus == null ? '' : String(rawStatus);

channelMap.put('middlewareStatusCode', statusText);

var statusCode = Number(statusText);

if (
    !/^[0-9]{3}$/.test(statusText) ||
    statusCode < 200 ||
    statusCode >= 300
) {
    channelMap.put(
        'gatewayErrorStatusCode',
        /^[45][0-9]{2}$/.test(statusText) ? statusText : '502'
    );

    channelMap.put(
        'gatewayError',
        responseBody.trim() !== ''
            ? responseBody
            : JSON.stringify({
                resourceType: 'OperationOutcome',
                issue: [{
                    severity: 'error',
                    code: 'exception',
                    diagnostics:
                        'Middleware lieferte keinen Response-Body'
                }]
            })
    );

    logger.warn(
        'Middleware HTTP-Status=' + statusText +
        ' - kein HAPI-Write'
    );

    return;
}

if (responseBody.trim() === '') {
    throw 'Middleware lieferte keinen Response-Body';
}

var responseTarget =
    String(channelMap.get('responseTarget') || 'none');

if (responseTarget !== 'hapi') {
    logger.info(
        'responseTarget=' + responseTarget +
        ' - kein HAPI-Write'
    );

    return;
}

var parsed;

try {
    parsed = JSON.parse(responseBody);
} catch (e) {
    throw 'Middleware-Antwort ist kein gueltiges JSON: ' + e;
}

if (
    parsed == null ||
    typeof parsed !== 'object' ||
    Array.isArray(parsed)
) {
    throw 'Middleware-Antwort ist keine FHIR-Ressource';
}

var resourceType = String(parsed.resourceType || '');

if (resourceType === 'OperationOutcome') {
    channelMap.put('gatewayError', responseBody);
    channelMap.put('gatewayErrorStatusCode', '502');

    logger.warn(
        'Middleware lieferte OperationOutcome - kein HAPI-Write'
    );

    return;
}

if (resourceType !== 'Bundle') {
    throw 'Unerwarteter resourceType: ' + resourceType;
}

if (
    parsed.type !== 'transaction' &&
    parsed.type !== 'batch'
) {
    throw 'Bundle ist nicht schreibbar: type=' + parsed.type;
}

channelMap.put('fhirJson', responseBody);

logger.info('FHIR JSON Laenge: ' + responseBody.length);

com.mirth.connect.plugins.javascriptrule.script:
var method =
    String(sourceMap.get('method') || '')
    .toUpperCase();

return method == 'POST'
    && String($('targetUrl') || '') !== ''
    && String($('gatewayError') || '') === '';

com.mirth.connect.plugins.javascriptstep.script:
channelMap.remove('finalResponse');
channelMap.remove('hapiStatusCode');

var rawResponse = response.getMessage();
var responseBody =
    rawResponse == null ? '' : String(rawResponse);

var rawStatus = connectorMap.get('responseStatusCode');
var statusText =
    rawStatus == null ? '' : String(rawStatus);

/*
 * HAPI-Status und Body fuer Destination 99 bereitstellen.
 * Auch Fehlerantworten unveraendert weitergeben.
 */
channelMap.put('hapiStatusCode', statusText);
channelMap.put('finalResponse', responseBody);

if (!/^[2-5][0-9]{2}$/.test(statusText)) {
    logger.error(
        'HAPI: fehlender oder ungueltiger HTTP-Status'
    );
    return;
}

if (responseBody.trim() === '') {
    logger.error('HAPI lieferte keinen Response-Body');
    return;
}

logger.info(
    'HAPI HTTP-Status=' + statusText +
    ', Response Laenge=' + responseBody.length
);

com.mirth.connect.plugins.javascriptrule.script:
var method =
    String(sourceMap.get('method') || '')
    .toUpperCase();

var responseTarget =
    String(channelMap.get('responseTarget') || 'none');

var gatewayError =
    String(channelMap.get('gatewayError') || '');

var fhirJson =
    String(channelMap.get('fhirJson') || '');

return (
    method === 'POST' &&
    responseTarget === 'hapi' &&
    gatewayError === '' &&
    fhirJson.trim() !== ''
);

com.mirth.connect.plugins.javascriptstep.script:
var body = response.getMessage();
var statusLine = connectorMap.get('responseStatusLine');

if (body == null) {
    throw new Error('Epic JWKS: response body is missing');
}

var match = /^HTTP\/\S+\s+([0-9]{3})\b/.exec(
    String(statusLine || '')
);

if (match == null) {
    throw new Error(
        'Epic JWKS: cannot read HTTP status; responseStatusLine=' +
        statusLine
    );
}

channelMap.put('epicJwksResponse', String(body));
channelMap.put('epicJwksStatusCode', match[1]);

com.mirth.connect.plugins.javascriptrule.script:
var path =
    String(sourceMap.get('uri') || '')
    .split('?')[0]
    .toLowerCase();

var method =
    String(sourceMap.get('method') || '')
    .toUpperCase();

return (
    method === 'GET' &&
    path === '/v1/.well-known/jwks.json' &&
    String(channelMap.get('gatewayError') || '') === ''
);

com.mirth.connect.plugins.javascriptstep.script:
function setClientResponse(body, status) {
    responseMap.put('responseStatusCode', String(status));
    msg = String(body);
}

function setGatewayFailure(diagnostics) {
    logger.error(diagnostics);

    setClientResponse(
        JSON.stringify({
            resourceType: 'OperationOutcome',
            issue: [{
                severity: 'error',
                code: 'exception',
                diagnostics: diagnostics
            }]
        }),
        '502'
    );
}

function forwardResponse(body, status, source) {
    var statusText = status == null ? '' : String(status);

    if (!/^[2-5][0-9]{2}$/.test(statusText)) {
        setGatewayFailure(
            source + ': missing or invalid HTTP status'
        );
        return;
    }

    setClientResponse(body, statusText);
}

var epicJwksResponse = channelMap.get('epicJwksResponse');
var gatewayError = channelMap.get('gatewayError');
var finalResponse = channelMap.get('finalResponse');
var middlewareResponse = channelMap.get('middlewareResponse');

var responseTarget =
    String(channelMap.get('responseTarget') || 'none');

if (gatewayError != null) {

    var errorStatus =
        String(channelMap.get('gatewayErrorStatusCode') || '');

    if (!/^[45][0-9]{2}$/.test(errorStatus)) {
        errorStatus = '400';

        try {
            var errorObj = JSON.parse(String(gatewayError));

            if (
                errorObj &&
                errorObj.issue &&
                errorObj.issue.length > 0 &&
                errorObj.issue[0].code === 'not-found'
            ) {
                errorStatus = '404';
            }
        } catch (e) {
            logger.warn(
                'Could not parse gatewayError: ' + String(e)
            );

            errorStatus = '502';
        }
    }

    setClientResponse(gatewayError, errorStatus);

} else if (epicJwksResponse != null) {

    forwardResponse(
        epicJwksResponse,
        channelMap.get('epicJwksStatusCode'),
        'Epic JWKS'
    );

} else if (responseTarget === 'hapi') {

    if (
        finalResponse == null ||
        String(finalResponse).trim() === ''
    ) {
        setGatewayFailure(
            'HAPI import: no response available'
        );
    } else {
        forwardResponse(
            finalResponse,
            channelMap.get('hapiStatusCode'),
            'HAPI'
        );
    }

} else if (middlewareResponse != null) {

    forwardResponse(
        middlewareResponse,
        channelMap.get('middlewareStatusCode'),
        'Middleware'
    );

} else {

    setGatewayFailure('No response available');

}

channel.postprocessingScript:
// This script executes once after a message has been processed
// Responses returned from here will be stored as "Postprocessor" in the response map
return;

channel.deployScript:
// This script executes once when the channel is deployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;

channel.undeployScript:
// This script executes once when the channel is undeployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;

properties.code:
function olCoreGetHeader(headers, name) {
    if (headers == null) {
        return '';
    }

    var value = headers.getHeader(name);
    return value == null ? '' : String(value);
}

function olCoreReadHttpRequest(source, rawBody) {
    var uri = String(source.get('uri') || '');
    var queryIndex = uri.indexOf('?');

    return {
        method: String(source.get('method') || '').toUpperCase(),
        path: (
            queryIndex >= 0 ? uri.substring(0, queryIndex) : uri
        ).toLowerCase(),
        query: queryIndex >= 0 ? uri.substring(queryIndex) : '',
        body: String(rawBody),
        authorization: olCoreGetHeader(
            source.get('headers'),
            'Authorization'
        )
    };
}

function olCoreSetGatewayError(target, status, code, diagnostics) {
    var statusText = String(status);

    if (!/^[45][0-9][0-9]$/.test(statusText)) {
        throw new Error('olCoreSetGatewayError: HTTP status must be 400-599');
    }
    if (code == null || String(code) === '' ||
        diagnostics == null || String(diagnostics) === '') {
        throw new Error('olCoreSetGatewayError: code and diagnostics are required');
    }

    target.put('gatewayError', JSON.stringify({
        resourceType: 'OperationOutcome',
        issue: [{
            severity: 'error',
            code: String(code),
            diagnostics: String(diagnostics)
        }]
    }));
    target.put('gatewayErrorStatusCode', statusText);
}

function olRouteApply(request, target, middlewareBaseUrl, log) {
    target.put('middlewareAuthorization', request.authorization);
    target.put('requestBody', request.body);
    target.put('targetMethod', request.method);
    target.put('responseTarget', 'none');

    log.info('PATH=' + request.path);
    log.info('METHOD=' + request.method);

    var route = olRouteResolve(request.method, request.path);

    if (route == null) {
        olCoreSetGatewayError(
            target, 404, 'not-found',
            'Unknown endpoint: ' + request.path
        );
        log.warn(
            'Unknown endpoint: method=' + request.method +
            ', path=' + request.path
        );
        return;
    }

    if (middlewareBaseUrl == null || String(middlewareBaseUrl) === '') {
        throw new Error('olRouteApply: middlewareBaseUrl is required');
    }

    if (route.checkCdaEncoding) {
        var corrupted =
               request.body.indexOf('\u00c3') >= 0
            || request.body.indexOf('\u00c2') >= 0
            || request.body.indexOf('\ufffd') >= 0;

        log.info(
            'CDA encoding check: corrupted=' + corrupted +
            ', length=' + request.body.length
        );

        if (corrupted) {
            olCoreSetGatewayError(
                target, 400, 'invalid',
                'CDA enth\u00e4lt fehlerhafte Zeichenkodierung. Bitte den Request mit Content-Type: application/xml; charset=UTF-8 senden.'
            );
            log.warn('CDA encoding problem detected - request rejected');
            return;
        }
    }

    target.put(
        'targetUrl',
        String(middlewareBaseUrl) + route.middlewarePath +
        (route.forwardQuery ? request.query : '')
    );
    target.put('responseTarget', route.responseTarget);

    if (route.emptyBody) {
        target.put('requestBody', '');
    }

    log.info('Routing -> ' + route.logMessage);
}

function olRouteResolve(method, path) {
    var routes = [
        {
            id: 'vacd.convert', method: 'POST',
            path: '/v1/cda/vacd/convert',
            middlewarePath: '/cda/vacd/convert',
            responseTarget: 'none', forwardQuery: true,
            logMessage: 'VACD (' + path + '), responseTarget=none'
        },
        {
            id: 'vacd.import', method: 'POST',
            path: '/v1/cda/vacd/import',
            middlewarePath: '/cda/vacd/prepare',
            responseTarget: 'hapi', forwardQuery: true,
            logMessage: 'VACD (' + path + '), responseTarget=hapi'
        },
        {
            id: 'cda.convert', method: 'POST',
            path: '/v1/cda/convert',
            middlewarePath: '/cda/convert',
            responseTarget: 'none', forwardQuery: true,
            checkCdaEncoding: true,
            logMessage: 'CDA (' + path + '), responseTarget=none'
        },
        {
            id: 'cda.import', method: 'POST',
            path: '/v1/cda/import',
            middlewarePath: '/cda/convert',
            responseTarget: 'hapi', forwardQuery: true,
            checkCdaEncoding: true,
            logMessage: 'CDA (' + path + '), responseTarget=hapi'
        },
        {
            id: 'emediplan.import', method: 'POST',
            path: '/v1/emediplan/import',
            middlewarePath: '/emediplan/prepare',
            responseTarget: 'hapi',
            logMessage: 'eMediplan preparation, responseTarget=hapi'
        },
        {
            id: 'emediplan.convert', method: 'POST',
            path: '/v1/emediplan/convert',
            middlewarePath: '/emediplan/convert',
            responseTarget: 'none',
            logMessage: 'eMediplan conversion, responseTarget=none'
        },
        {
            id: 'echosos.resolve', method: 'POST',
            path: '/v1/echosos/resolve',
            middlewarePath: '/echosos/qr',
            responseTarget: 'hapi',
            logMessage: 'EchoSOS'
        },
        {
            id: 'epic.jwks', method: 'GET',
            path: '/v1/.well-known/jwks.json',
            middlewarePath: '/.well-known/jwks.json',
            responseTarget: 'none', emptyBody: true,
            logMessage: 'Epic JWKS'
        }
    ];

    for (var i = 0; i < routes.length; i++) {
        if (routes[i].method === method && routes[i].path === path) {
            return routes[i];
        }
    }

    return null;
}

function omniLinkJwtAuthenticate() {

    var Base64 = Packages.java.util.Base64;
    var StandardCharsets = Packages.java.nio.charset.StandardCharsets;
    var Signature = Packages.java.security.Signature;
    var CertificateFactory = Packages.java.security.cert.CertificateFactory;
    var ByteArrayInputStream = Packages.java.io.ByteArrayInputStream;
    var KeyFactory = Packages.java.security.KeyFactory;
    var RSAPublicKeySpec = Packages.java.security.spec.RSAPublicKeySpec;
    var BigInteger = Packages.java.math.BigInteger;


    function reject(reason) {
        logger.warn('JWT Auth abgelehnt: ' + reason);
        return AuthenticationResult.Failure();
    }

    function decodeJson(part) {
        var bytes = Base64.getUrlDecoder().decode(String(part));
        var text = new java.lang.String(bytes, StandardCharsets.UTF_8);
        return JSON.parse(String(text));
    }

    function readUrl(url) {

        var HttpClients =
            Packages.org.apache.http.impl.client.HttpClients;

        var HttpGet =
            Packages.org.apache.http.client.methods.HttpGet;

        var RequestConfig =
            Packages.org.apache.http.client.config.RequestConfig;

        var EntityUtils =
            Packages.org.apache.http.util.EntityUtils;

        var config = RequestConfig
            .custom()
            .setConnectTimeout(3000)
            .setSocketTimeout(3000)
            .setConnectionRequestTimeout(3000)
            .build();

        var client = HttpClients
            .custom()
            .setDefaultRequestConfig(config)
            .build();

        var request = new HttpGet(String(url));
        request.setHeader('Accept', 'application/json');

        var response = null;

        try {
            response = client.execute(request);

            var status =
                response.getStatusLine().getStatusCode();

            if (status < 200 || status >= 300) {
                throw 'JWKS HTTP Fehler: ' + status;
            }

            return String(
                EntityUtils.toString(
                    response.getEntity(),
                    StandardCharsets.UTF_8
                )
            );

        } finally {

            if (response != null) {
                response.close();
            }

            client.close();
        }
    }

    function getJwks(forceRefresh) {
        var cacheKey = 'omnilink.jwt.jwks';
        var cacheTimeKey = 'omnilink.jwt.jwks.time';
        var maxAge = 600000;
        var now = new Date().getTime();

        if (!forceRefresh) {
            var cached = globalMap.get(cacheKey);
            var cachedAt = globalMap.get(cacheTimeKey);

            if (cached != null && cachedAt != null) {
                if ((now - Number(String(cachedAt))) < maxAge) {
                    return JSON.parse(String(cached));
                }
            }
        }

        var json = readUrl(String($cfg('jwt.jwksUrl')));

        globalMap.put(cacheKey, json);
        globalMap.put(cacheTimeKey, String(now));

        return JSON.parse(json);
    }

    function findKey(kid) {
        var jwks = getJwks(false);

        for (var i = 0; i < jwks.keys.length; i++) {
            if (String(jwks.keys[i].kid) === String(kid)) {
                return jwks.keys[i];
            }
        }

        // Falls Keycloak gerade den Signing Key gewechselt hat
        jwks = getJwks(true);

        for (var j = 0; j < jwks.keys.length; j++) {
            if (String(jwks.keys[j].kid) === String(kid)) {
                return jwks.keys[j];
            }
        }

        return null;
    }

    function createPublicKey(jwk) {

        if (jwk.x5c != null && jwk.x5c.length > 0) {

            var certBytes =
                Base64.getDecoder().decode(String(jwk.x5c[0]));

            var cert =
                CertificateFactory
                    .getInstance('X.509')
                    .generateCertificate(
                        new ByteArrayInputStream(certBytes)
                    );

            return cert.getPublicKey();
        }

        if (jwk.n != null && jwk.e != null) {

            var modulus = new BigInteger(
                1,
                Base64.getUrlDecoder().decode(String(jwk.n))
            );

            var exponent = new BigInteger(
                1,
                Base64.getUrlDecoder().decode(String(jwk.e))
            );

            var spec = new RSAPublicKeySpec(modulus, exponent);

            return KeyFactory
                .getInstance('RSA')
                .generatePublic(spec);
        }

        throw 'Kein verwendbarer RSA Public Key im JWKS';
    }

    function hasRealmRole(claims, requiredRole) {

        if (requiredRole == null || requiredRole === '') {
            return true;
        }

        if (claims.realm_access == null ||
            claims.realm_access.roles == null) {
            return false;
        }

        var roles = claims.realm_access.roles;

        for (var i = 0; i < roles.length; i++) {
            if (String(roles[i]) === String(requiredRole)) {
                return true;
            }
        }

        return false;
    }

    function isAllowedClient(clientId) {

        var cfg = String($cfg('jwt.allowedClients') || '');

        var clients = cfg.split(',');

        for (var i = 0; i < clients.length; i++) {

            if (String(clients[i]).trim() === String(clientId)) {
                return true;
            }
        }

        return false;
    }

    try {

        var headers = sourceMap.get('headers');

        if (headers == null) {
            return reject('HTTP Header fehlen');
        }

        /*
         * Bei Mirth/BridgeLink ist der Header-Container das Objekt
         * unter sourceMap["headers"].
         */
       var authorization = headers.getHeader('Authorization');

       if (authorization == null) {
            authorization = headers.getHeader('authorization');
       }
        logger.info(
              'Authorization Header vorhanden=' +
              (authorization != null)
       );
        if (authorization == null ||
            String(authorization).trim() === '') {
            return reject('Authorization Header fehlt');
        }

        /*
         * Mirth kann Header-Werte als Liste liefern.
         * Beispiel:
         * [Bearer eyJ...]
         */
        var auth = String(authorization).trim();

        if (auth.charAt(0) === '[' &&
            auth.charAt(auth.length - 1) === ']') {
            auth = auth.substring(1, auth.length - 1);
        }

        if (auth.indexOf('Bearer ') !== 0) {
            return reject('Kein Bearer Token');
        }

        var token = auth.substring(7).trim();
        var parts = token.split('.');

        if (parts.length !== 3) {
            return reject('JWT Format ungültig');
        }

        var jwtHeader = decodeJson(parts[0]);
        var claims = decodeJson(parts[1]);

        if (String(jwtHeader.alg) !== 'RS256') {
            return reject(
                'Nicht erlaubter JWT Algorithmus: ' +
                String(jwtHeader.alg)
            );
        }

        if (jwtHeader.kid == null) {
            return reject('JWT kid fehlt');
        }

        var jwk = findKey(jwtHeader.kid);

        if (jwk == null) {
            return reject('Signing Key nicht gefunden');
        }

        var publicKey = createPublicKey(jwk);

        var verifier = Signature.getInstance('SHA256withRSA');
        verifier.initVerify(publicKey);

        var signedData = parts[0] + '.' + parts[1];

        verifier.update(
            new java.lang.String(signedData)
                .getBytes(StandardCharsets.US_ASCII)
        );

        var signatureBytes =
            Base64.getUrlDecoder().decode(String(parts[2]));

        if (!verifier.verify(signatureBytes)) {
            return reject('JWT Signatur ungültig');
        }

        var issuer = String($cfg('jwt.issuer'));

        if (String(claims.iss) !== issuer) {
            return reject(
                'Issuer ungültig: ' + String(claims.iss)
            );
        }

        var now = Math.floor(new Date().getTime() / 1000);

        if (claims.exp == null || Number(claims.exp) <= now) {
            return reject('JWT abgelaufen');
        }

        if (claims.nbf != null &&
            Number(claims.nbf) > now + 30) {
            return reject('JWT noch nicht gültig');
        }

        if (claims.iat != null &&
            Number(claims.iat) > now + 60) {
            return reject('JWT iat liegt in der Zukunft');
        }

        var clientId = '';

        if (claims.azp != null) {
            clientId = String(claims.azp);
        } else if (claims.client_id != null) {
            clientId = String(claims.client_id);
        }

        if (clientId === '') {
            return reject('client_id / azp fehlt');
        }

        if (!isAllowedClient(clientId)) {
            return reject(
                'Client nicht erlaubt: ' + clientId
            );
        }

        var requiredRole =
            String($cfg('jwt.requiredRole') || '');

        if (!hasRealmRole(claims, requiredRole)) {
            return reject(
                'Realm-Rolle fehlt: ' + requiredRole
            );
        }

        /*
         * Kein komplettes Token loggen.
         */
        logger.info(
            'JWT Auth erfolgreich: client=' +
            clientId +
            ', sub=' +
            String(claims.sub)
        );

        return AuthenticationResult.Success();

    } catch (e) {

        logger.error(
            'JWT Auth Fehler: ' + String(e)
        );

        return AuthenticationResult.Failure();
    }
}
